// Link gap (full runs): the domains that link to at least one competitor but not to you (backlinks/domain_intersection; the linking domain is the
// item's `target` field), one request per site.
// Competitors: configured, kept from earlier runs, or picked now from the Labs competitors (big platforms and the site itself excluded).
const API = 'https://api.dataforseo.com/v3/';
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
const reqs = $('BL Requests').all().map(i => i.json); let resps = []; try { resps = $('Run BL Requests Answers').all().map(i => i.json || {}); } catch (e) {}   // not run on a free-sources-only check
const BIG = /(^|\.)(google|youtube|facebook|linkedin|wikipedia|amazon|apple|microsoft|reddit|quora|instagram|x|twitter|tiktok|medium|github|indeed|glassdoor|gov)\./i;
const out = [];
for (const p of plans) {
  let comps = [...p.competitors];
  if (!comps.length) { const i = reqs.findIndex(r => r.site_id === p.site_id && r.kind === 'competitors'); const items = i >= 0 ? (((resps[i].tasks || [])[0] || {}).result || [{}])[0]?.items || [] : [];
    comps = items.map(x => String(x.domain || '').replace(/^www\./, '')).filter(d => d && d !== p.domain && !BIG.test(d + '.') && !/\.gov(\.|$)/.test(d)).slice(0, 3); }
  if (p.mode !== 'full' || !p.gap_due || !comps.length || p.free_only) continue;   // quarterly (v4.6): between refreshes the stored gap prospects are shown
  const targets = {}; comps.forEach((c, i) => { targets[String(i + 1)] = c; });
  out.push({ json: { site_id: p.site_id, domain: p.domain, kind: 'gap', competitors: comps, endpoint: API + 'backlinks/domain_intersection/live', body: [{ targets, exclude_targets: [p.domain], intersection_mode: 'partial', limit: 100, order_by: ['1.rank,desc'] }] } });   // partial = links to at least one competitor (verified live 2026-10-02)
}
return out.length ? out : [{ json: { skip: true } }];

// Free link and mention sources (v4.10, no key, $0), one GET per item for *Fetch Sources*:
// - Wikipedia (MediaWiki exturlusage, English + the site's language, full runs): articles that cite the site (namespace 0 kept; asking the
//   API for namespace 0 with a wildcard returns an empty first batch). Nofollow, but the source AI assistants and journalists trust most.
//   Wikimedia's robot policy: one request at a time, a descriptive User-Agent (*Fetch Sources* sends one).
// - Hacker News (Algolia, full runs): stories that link to the site.
// - Web search through the stack's own SearXNG (full runs): pages naming the brand outside the site (unlinked mentions are checked later by
//   fetching the page) and "best <topic> in <country>" list pages (which competitors they name, and whether they name you).
// GDELT news is fetched separately (*News Requests*: its API allows one request every 5 seconds). Reddit refuses unauthenticated requests
// (403 since May 2026; its API needs an approved app and a commercial agreement) and Google News RSS is for personal, non-commercial use
// only: neither is used.
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
const out = [];
const add = (p, kind, url, extra = {}) => out.push({ json: { site_id: p.site_id, domain: p.domain, kind, url, ...extra } });
const enc = encodeURIComponent;
for (const p of plans) {
  if (p.mode !== 'full') continue;
  const langs = [...new Set(['en', String(p.language_code || 'en').slice(0, 2).toLowerCase()])].filter(l => /^[a-z]{2}$/.test(l));
  for (const lang of langs) for (const q of [p.domain])   // the plain domain also matches its subdomains (checked live 2026-10-08)
    add(p, 'wiki', 'https://' + lang + '.wikipedia.org/w/api.php?action=query&list=exturlusage&format=json&euprop=ids|title|url&eulimit=500&euquery=' + enc(q), { lang });
  add(p, 'hn', 'https://hn.algolia.com/api/v1/search?restrictSearchableAttributes=url&tags=story&hitsPerPage=100&query=' + enc(p.domain));
  add(p, 'searx_mention', 'http://searxng:8080/search?format=json&q=' + enc('"' + p.brand_query + '" -site:' + p.domain));
  if (p.brand_query !== p.domain) add(p, 'searx_mention', 'http://searxng:8080/search?format=json&q=' + enc('"' + p.domain + '" -site:' + p.domain));
  for (const t of (p.topics || []).slice(0, 2)) add(p, 'searx_list', 'http://searxng:8080/search?format=json&q=' + enc('best ' + t + (p.country_name && !t.includes(p.country_name.toLowerCase()) ? ' ' + p.country_name : '')), { topic: t });
}
return out.length ? out : [{ json: { skip: true } }];

// News that names the business (v4.10, GDELT DOC 2.0 API, free; one request every 5 seconds, so *Fetch News* runs one at a time with a 5.5 s
// pause): articles from the past week (light runs) or 3 months (full runs) in 65 languages. Each article is checked later by fetching it —
// a mention without a link is an outreach prospect, one with a link joins the ledger. The query is the business name when it is distinctive,
// else the domain (a short label like "techand" matches other companies).
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do);
const out = [];
for (const p of plans) {
  const q = '"' + String(p.brand_query).replace(/"/g, '') + '"';
  out.push({ json: { site_id: p.site_id, domain: p.domain, kind: 'gdelt', url: 'https://api.gdeltproject.org/api/v2/doc/doc?mode=artlist&format=json&sort=datedesc&maxrecords=' + (p.mode === 'full' ? 75 : 25) + '&timespan=' + (p.mode === 'full' ? '3months' : '8days') + '&query=' + encodeURIComponent(q) } });
}
return out.length ? out : [{ json: { skip: true } }];

// Bing Webmaster Tools (v4.10, free; only when SEO_BING_WEBMASTER_API_KEY is in n8n/.env): Bing's own crawl of the links to your site. The key
// belongs to one Bing account and reads every site verified in it — add a site there (Search Console import: one click, verified at once)
// or have its owner add that account under Settings → Users (read-only). First the account's sites, to use each site's exact URL.
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do && p.bing);
return plans.length ? [{ json: { kind: 'bing_sites', url: 'https://ssl.bing.com/webmaster/api.svc/json/GetUserSites' } }] : [{ json: { skip: true } }];

// Bing: the site's pages that have inbound links (GetLinkCounts, two result pages), for the sites the Bing account can read. A site Bing
// does not know is reported ("add it to Bing Webmaster Tools") and costs nothing.
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do && p.bing);
let sites = []; try { const r = $('Fetch Bing Sites').first().json || {}; const j = (r.body && typeof r.body === 'object') ? r.body : (typeof r.data === 'string' ? JSON.parse(r.data) : (r.d ? r : {})); sites = (j.d || []).filter(s => s && s.Url); } catch (e) {}
const host = (u) => String(u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^www\./, '').replace(/[\/?#].*$/, '');
const out = [];
for (const p of plans) {
  const s = sites.find(x => host(x.Url) === p.domain && x.IsVerified !== false) || sites.find(x => host(x.Url) === p.domain);
  if (!s) continue;
  for (const page of [0, 1]) out.push({ json: { site_id: p.site_id, domain: p.domain, kind: 'bing_counts', site_url: s.Url, url: 'https://ssl.bing.com/webmaster/api.svc/json/GetLinkCounts?siteUrl=' + encodeURIComponent(s.Url) + '&page=' + page } });
}
return out.length ? out : [{ json: { skip: true, sites: sites.length } }];

// Bing: the linking pages and anchors for the site's most-linked pages (GetUrlLinks, first result page each; up to 15 pages per site on
// full runs, 5 on light runs). Bing gives no dates and no nofollow flag: the link check reads both from the page itself.
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do && p.bing);
let reqs = [], resps = []; try { reqs = $('Bing Requests').all().map(i => i.json); resps = $('Fetch Bing Counts').all().map(i => i.json || {}); } catch (e) {}
const parse = (r) => { if (!r) return {}; if (r.body && typeof r.body === 'object') return r.body; if (r.d) return r; try { return JSON.parse(String(r.body ?? r.data ?? '')); } catch (e) { return {}; } };
const out = [];
for (const p of plans) {
  const counts = []; reqs.forEach((r, i) => { if (r.site_id === p.site_id && r.kind === 'bing_counts') { const d = parse(resps[i]).d; for (const l of ((d || {}).Links || [])) counts.push({ url: l.Url, count: Number(l.Count) || 0, site_url: r.site_url }); } });
  const top = counts.filter((c, i, a) => c.url && a.findIndex(x => x.url === c.url) === i).sort((a, b) => b.count - a.count).slice(0, p.mode === 'full' ? 15 : 5);
  for (const c of top) out.push({ json: { site_id: p.site_id, domain: p.domain, kind: 'bing_links', link: c.url, count: c.count, url: 'https://ssl.bing.com/webmaster/api.svc/json/GetUrlLinks?siteUrl=' + encodeURIComponent(c.site_url) + '&link=' + encodeURIComponent(c.url) + '&page=0' } });
}
return out.length ? out : [{ json: { skip: true } }];

// Links that send people (v4.10, GA4 Data API, free; the service account needs Viewer access to the property — the Site Tracker's connect step):
// every referral source of the past year with visits, engaged visits, key events and revenue (365 days) and the past 28 days, and the exact
// referring pages (pageReferrer, the site's own pages excluded). A referrer that sends visits is a live link, whatever any index says, and
// the visits are the link's referral value. E-mail, chat, search and payment hosts are filtered out later (LK.domainKind).
const plans = $('BL Plan').all().map(i => i.json).filter(p => !p.nothing_to_do && p.ga4_property_id);
if (!plans.length) return [{ json: { skip: true, reason: 'no GA4 property on file (connect GA4 through "Track my site"; the Site Tracker stores the property it detects)' } }];
const MET = ['sessions', 'engagedSessions', 'keyEvents', 'totalRevenue'].map(name => ({ name }));
const REF = { filter: { fieldName: 'sessionMedium', stringFilter: { matchType: 'EXACT', value: 'referral' } } };
const out = [];
for (const p of plans) {
  const url = 'https://analyticsdata.googleapis.com/v1beta/properties/' + p.ga4_property_id + ':runReport';
  const notSelf = { notExpression: { filter: { fieldName: 'pageReferrer', stringFilter: { matchType: 'CONTAINS', value: p.domain, caseSensitive: false } } } };
  out.push({ json: { site_id: p.site_id, kind: 'ref_sources', url, body: { dateRanges: [{ startDate: '365daysAgo', endDate: 'yesterday', name: 'year' }, { startDate: '28daysAgo', endDate: 'yesterday', name: 'recent' }], dimensions: [{ name: 'sessionSource' }], metrics: MET, dimensionFilter: REF, orderBys: [{ metric: { metricName: 'sessions' }, desc: true }], limit: 500 } } });
  out.push({ json: { site_id: p.site_id, kind: 'ref_pages', url, body: { dateRanges: [{ startDate: '365daysAgo', endDate: 'yesterday' }], dimensions: [{ name: 'pageReferrer' }, { name: 'sessionSource' }], metrics: [{ name: 'sessions' }, { name: 'keyEvents' }], dimensionFilter: { andGroup: { expressions: [REF, notSelf] } }, orderBys: [{ metric: { metricName: 'sessions' }, desc: true }], limit: 500 } } });
}
return out;

// One list of who links to the site, from every source (v4.10, BACKLINKS_SPEC.md §3): DataForSEO (referring domains + one link per domain with
// its details, new / lost), Bing Webmaster Tools (its own crawl, verified sites), the Search Console link exports the person uploaded (Google's
// own sample), GA4 referrals (links that send visits), Wikipedia and Hacker News, the Common Crawl web graph (133M domains, refreshed monthly by
// the linkgraph job: seo_link_graph), and the ledger of earlier runs. Keyed by referring site
// (registrable domain; platform subdomains such as x.blogspot.com stay separate). E-mail, chat, search, payment and AI hosts from GA4 are not
// links on the web and are dropped; social networks are kept and marked. Also collects the pages to check for mentions (news, web search,
// Content Analysis) and the "best X" list pages. Per site one item; *Verify Requests* decides what to fetch.
// ---- link kit (v4.10, inlined by build_monitors.py): reads a fetched page the way a link checker does — the links to a site with their rel,
// anchor and placement, page facts (noindex, canonical, outbound links, language) and contact e-mails. Regex only: the n8n sandbox has no URL
